#include <cstdio>
#include <cstdlib>
#include <vector>
#include <cstdint>

// C++ part: Rust sees this as a nested block comment.
typedef std::vector<uint32_t> Big; // base 1e9, little-endian

static Big add(const Big &a, const Big &b) {
    Big r;
    uint64_t carry = 0;
    for (size_t i = 0; i < a.size() || i < b.size() || carry; i++) {
        uint64_t s = carry;
        if (i < a.size()) s += a[i];
        if (i < b.size()) s += b[i];
        r.push_back((uint32_t)(s % 1000000000ULL));
        carry = s / 1000000000ULL;
    }
    return r;
}

int main(int argc, char **argv) {
    long long n = argc > 1 ? atoll(argv[1]) : 0;
    Big a(1, 1), b(1, 1);
    for (long long i = 0; i < n; i++) {
        Big c = add(a, b);
        a = b;
        b = c;
    }
    printf("%u", a.back());
    for (size_t i = a.size() - 1; i-- > 0;) printf("%09u", a[i]);
    printf("\n");
